def remote_urls(niche: str) -> list:
    return [CDN + i for i in REMOTE.get(niche, [])]


def sized(url: str, w: int, q: int = 70) -> str:
    """Unsplash resizes on the fly; ask for exactly the width the slot uses."""
    return f"{url}?w={w}&q={q}&auto=format&fit=crop"
